'use strict';
const {guide,parts,prints,electrical,plateSettingsHTML}=window.BGB;
const REPO='https://github.com/demartinistudios/blooglyblob';
const $=s=>document.querySelector(s),escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const partMap=Object.fromEntries(parts.map(p=>[p.id,p]));
const buildSteps=guide.steps.filter(s=>s.kind==='build');
const stepMap=Object.fromEntries(guide.steps.map(s=>[s.id,s]));
const printedPieceCount=parts.filter(p=>p.category==='Printed'&&p.qty>0).reduce((n,p)=>n+p.qty,0);
const routeAliases={'fb-nuts':'fb-base-nuts','fb-harness':'fb-inlet','fb-fuse-leads':'fb-servo-power'};
const stepName=id=>stepMap[id]?.kind==='service'?'“'+stepMap[id].title+'”':'step '+stepMap[id]?.number;
const stepLink=old=>{const id=routeAliases[old]||old;return stepMap[id]?`<a href="#step-${id}">${escape(stepName(id))}</a>`:escape(id)};
// Authored text is escaped, then code, step references and the tool-list link become markup.
const rich=t=>escape(t).replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\{step:([\w-]+)\}/g,(_,id)=>stepLink(id)).replaceAll('{tools}','<a href="#parts/tools">tool list</a>');
const plain=t=>String(t??'').replace(/`([^`]+)`/g,'$1').replace(/\{step:([\w-]+)\}/g,(_,id)=>stepName(id)).replaceAll('{tools}','tool list');
const S=id=>stepLink(id);

// Progress lives in this browser only. The first visit imports the earlier preview's ticks once.
const KEY='blooglyblob-guide',OLD_KEY='bgb-r16-guide';
function currentFrontMounts(s){
 if(s.frontMountsVersion===1)return s;
 // Only these printed parts, increased hardware quantities and their joint changed.
 s.steps=s.steps.filter(id=>id!=='fb-panels');
 s.stock=s.stock.filter(id=>!['FB01','FB41','M3x6','N3'].includes(id));
 s.frontMountsVersion=1;
 try{localStorage.setItem(KEY,JSON.stringify(s))}catch{}
 return s;
}
function currentBaseMounts(s){
 if(s.baseMountsVersion===1)return s;
 const changed=['fb-panels','fb-shell','fb-nuts','fb-fuse-leads','fb-audio-cradle','fb-audio','fb-boards','fb-wagos','fb-fuses-capacitors','fb-power','fb-signals','fb-base-check','33','34','35','first-motion','system-check','fb-close','fb-closed-test'];
 s.steps=s.steps.filter(id=>!changed.includes(id));
 s.stock=s.stock.filter(id=>!['FB01','FB24','FB25','FB26'].includes(id));
 s.baseMountsVersion=1;
 try{localStorage.setItem(KEY,JSON.stringify(s))}catch{}
 return s;
}
function currentGuideFlow(s){
 if(s.guideFlowVersion===1)return s;
 const split={'fb-inlet-button':['fb-inlet'],'fb-power':['fb-servo-power','fb-light-power'],'14':['light-input']};
 s.steps=[...new Set(s.steps.flatMap(id=>[id,...(split[id]||[])]))].filter(id=>!Object.hasOwn(routeAliases,id));
 s.guideFlowVersion=1;
 try{localStorage.setItem(KEY,JSON.stringify(s))}catch{}
 return s;
}
function currentAudioMount(s){
 if(s.audioMountVersion===1)return s;
 s.steps=s.steps.filter(id=>!['fb-audio-cradle','fb-audio'].includes(id));
 s.stock=s.stock.filter(id=>!['FB24','C16'].includes(id));
 s.audioMountVersion=1;
 try{localStorage.setItem(KEY,JSON.stringify(s))}catch{}
 return s;
}
function currentSoftwareSetup(s){
 if(s.softwareSetupVersion===1)return s;
 // The previous single step covered the entire bench setup, not just flashing.
 if(s.steps.includes('software-prepare'))s.steps=[...new Set([...s.steps,'software-connect','software-configure','software-install'])];
 s.softwareSetupVersion=1;
 try{localStorage.setItem(KEY,JSON.stringify(s))}catch{}
 return s;
}
function currentBaseSlots(s){
 if(s.baseSlotsVersion===1)return s;
 // R27 changes only FB01 and these nut-loading/fastening operations.
 s.steps=s.steps.filter(id=>!['fb-base-nuts','fb-panels','fb-inlet','fb-audio-cradle'].includes(id));
 s.stock=s.stock.filter(id=>id!=='FB01');
 s.baseSlotsVersion=1;
 try{localStorage.setItem(KEY,JSON.stringify(s))}catch{}
 return s;
}
function currentBoardLayout(s){
 if(s.boardLayoutVersion===1)return s;
 // R28 changes FB01 mounting/layout and the associated wiring checks only.
 const changed=['fb-base-nuts','fb-boards','fb-wagos','fb-power','fb-servo-power','fb-light-power','fb-signals','fb-fuses-capacitors','fb-base-check','light-input','33','34','35','system-check','fb-close','fb-closed-test'];
 s.steps=s.steps.filter(id=>!changed.includes(id));
 s.stock=s.stock.filter(id=>id!=='FB01');
 s.boardLayoutVersion=1;
 try{localStorage.setItem(KEY,JSON.stringify(s))}catch{}
 return s;
}
function loadState(){
 try{const s=JSON.parse(localStorage.getItem(KEY)||'null');if(s&&Array.isArray(s.steps)&&Array.isArray(s.stock))return currentBoardLayout(currentBaseSlots(currentSoftwareSetup(currentAudioMount(currentGuideFlow(currentBaseMounts(currentFrontMounts(s)))))))}catch{}
 const s={steps:[],stock:[]};
 try{
  const old=JSON.parse(localStorage.getItem(OLD_KEY)||'null');
  if(old){
   const split={'04':['servo-cables'],'09':['eye-boards']};
   s.steps=[...new Set((old.steps||[]).flatMap(id=>[id,...(split[id]||[])]).filter(id=>stepMap[id]))];
   s.stock=[...new Set((old.stock||[]).filter(id=>partMap[id]&&!partMap[id].omitted))];
  }
 }catch{}
 try{localStorage.setItem(KEY,JSON.stringify(s))}catch{}
 return currentBoardLayout(currentBaseSlots(currentSoftwareSetup(currentAudioMount(currentGuideFlow(currentBaseMounts(currentFrontMounts(s)))))));
}
const state=loadState();
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{}updateProgress()}
function updateProgress(){const complete=buildSteps.filter(s=>state.steps.includes(s.id)).length;$('#progress-count').textContent=`${complete} / ${buildSteps.length}`;$('#progress').max=buildSteps.length;$('#progress').value=complete;document.querySelectorAll('[data-navstep]').forEach(a=>a.classList.toggle('done',state.steps.includes(a.dataset.navstep)))}

const mainRefs=[['start','Meet BlooglyBlob'],['notes','Build notes'],['safety','Safety & responsibility'],['parts','Parts & supplies'],['hardware','Fasteners & screw key'],['electrical','Electrical reference'],['software','Software reference'],['troubleshooting','Troubleshooting']];
const serviceRefs=guide.steps.filter(s=>s.kind==='service').map(s=>['step-'+s.id,s.title]);
const refs=[...mainRefs,...serviceRefs];
$('#reference-nav').innerHTML='<details id="reference-menu"><summary>Reference & service</summary>'+mainRefs.filter(([id])=>id!=='start').map(([id,n])=>`<a href="#${id}" data-route="${id}">${n}</a>`).join('')+'<h3>Service</h3>'+serviceRefs.map(([id,n])=>`<a href="#${id}" data-route="${id}">${escape(n)}</a>`).join('')+'</details>';
let chap='';$('#step-nav').innerHTML=buildSteps.map(s=>{const h=chap===s.chapter?'':`<h3>${escape(s.chapter)}</h3>`;chap=s.chapter;return h+`<a href="#step-${s.id}" data-route="step-${s.id}" data-navstep="${s.id}"><span class="num">${s.number}</span>${escape(s.title)}</a>`}).join('');

function stepNavigation(s){
 if(s.kind==='service')return '<div class="actions"><a class="button" href="#start">Meet BlooglyBlob</a><a class="button" href="#troubleshooting">Troubleshooting</a></div>';
 const i=buildSteps.findIndex(x=>x.id===s.id),prev=buildSteps[i-1],next=buildSteps[i+1];
 const done=next?'':`<div class="notice info build-complete"><b>Build complete.</b> Your robot is finished. Press the button and say hello. If you ever need to open it up, the Service pages cover the base, the head, the lighting and replacing a servo, and <a href="#troubleshooting">Troubleshooting</a> covers common problems.</div>`;
 const nextLink=next?`<a class="button primary next-step" data-next-step href="#step-${next.id}"><small>${next.chapter!==s.chapter?'Next chapter: '+escape(next.chapter):'Next'}</small>Step ${next.number} · ${escape(next.title)} →</a>`:'<a class="button primary" href="#start">Back to build overview</a>';
 return `${done}<div class="step-end"><label class="complete"><input type="checkbox" data-step="${s.id}" ${state.steps.includes(s.id)?'checked':''}>Done</label><div class="actions">${prev?`<a class="button" data-previous-step href="#step-${prev.id}">← Step ${prev.number}</a>`:''}${nextLink}</div></div>`;
}
function diagram(path,alt,caption=''){return `<figure class="diagram"><button data-zoom="${path}" aria-label="Enlarge ${escape(alt)}"><img src="${path}" alt="${escape(alt)}" loading="lazy"></button><figcaption><button class="enlarge-label" data-zoom="${path}" aria-label="Enlarge ${escape(alt)}">Enlarge diagram ↗</button>${caption}</figcaption></figure>`}
function table(head,rows,cls=''){return `<div class="table-wrap ${cls}"><table><thead><tr>${head.map(x=>`<th scope="col">${x}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map((x,i)=>`<td data-label="${escape(String(head[i]).replace(/<[^>]+>/g,''))}">${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function gather(items,hardware=false){if(!Object.keys(items).length)return `<p class="fine">${hardware?'No screws in this step.':'Only the assemblies you’ve already built.'}</p>`;return `<ul>${Object.entries(items).map(([id,n])=>{const name=partMap[id]?.name||id;const img=partMap[id]?.image;return `<li><a href="#parts/${id}">${img?`<img class="thumb" src="${escape(img)}" alt="" loading="lazy">`:''}<span class="gather-name">${escape(name)}${name.replace('×','x')===id?'':` <small>${id}</small>`}${typeof n==='number'?'':`<small class="gather-amount">${escape(n)}</small>`}</span></a><span>${typeof n==='number'?`× ${n}`:''}</span></li>`}).join('')}</ul>`}
const templates={'08':['downloads/eye-film-template.pdf','Download the full-size eye film template (PDF)'],'15':['downloads/body-foam-template.svg','Download the body foam template (SVG)']};
function standSupplies(){const s=stepMap['fb-stand'];return `<p>Only J05 is 3D printed. The base, two blocks and head riser are wood.</p>${table(['Qty','Material','Size / use'],s.workshop_supplies.map(row=>row.map(escape)),'cards')}<p><b>Tools:</b> ${escape(s.workshop_tools)}</p><div class="actions"><a href="downloads/service-stand-saddle-J05.stl" download>Download J05 saddle (STL)</a><a href="downloads/service-stand-template.svg" download>Download wood template (SVG)</a></div><p>Print the template at 100% and check its 100 mm scale bar, or mark out the dimensions with a ruler.</p>`}
function benchList(s){if(s.id==='fb-stand')return `<details class="bench-list single"><summary>You’ll need: printed saddle, wood, padding and screws</summary>${standSupplies()}</details>`;const nParts=Object.keys(s.parts).length,nHw=Object.keys(s.hardware).length;if(!nParts&&!nHw)return '';const tools=nParts&&Object.keys(s.parts).every(id=>partMap[id]?.category==='Tool');const count=[nParts?`${nParts} ${tools?'tool':'part'}${nParts>1?'s':''}`:'',nHw?`${nHw} fastener type${nHw>1?'s':''}`:''].filter(Boolean).join(', ');return `<details class="bench-list${nParts&&nHw?'':' single'}"><summary>You’ll need <span class="bench-count">${count}</span></summary><div class="gather">${nParts?`<section><h2>${tools?'Tools':'Parts'}</h2>${gather(s.parts)}</section>`:''}${nHw?`<section><h2>Fasteners</h2>${gather(s.hardware,true)}<a class="fine" href="#hardware">Match lengths on the screw key</a></section>`:''}</div></details>`}
function stepTips(s){return ['06','07','13','16','18'].includes(s.id)?`<p class="notice info"><b>Bench assembly only.</b> Keep the head and arms off their servo shafts. You’ll attach them in ${S('servo-position')}, after the power checks.</p>`:s.id==='34'?`<p class="notice info"><b>Keep the servo shafts bare.</b> The power checks come next, then you fit the head and arms in the fit pose.</p>`:''}
function stepLinks(s){if(s.id==='02')return '';const links=[];
 if(s.id==='01')links.push('<a class="button primary" href="#parts">Open Parts & supplies</a>','<a class="button" href="#notes">Build notes</a>');
 if(s.id==='fb-stand')links.push('<a class="button" href="#step-01">Back to workbench setup</a>');
 if(s.id.startsWith('software-'))links.push('<a class="button" href="#software">Software reference</a>');
 if(s.id==='servo-position')links.push('<a class="button" href="downloads/servo-fit-reference.md" download>Servo fit reference</a>');
 if(['12','14','33','35','fb-inlet','fb-servo-power','fb-light-power','light-input','fb-power','fb-signals','fb-base-check','system-check'].includes(s.id))links.push('<a class="button" href="#electrical">Open the wiring tables</a>');
 if(s.id==='light-input')links.push('<a class="button" href="https://learn.adafruit.com/adafruit-neopixel-uberguide/seed-pixels">Adafruit strand wiring</a>');
 links.push('<a class="button" href="references.html">Component datasheets</a>');
 return `<div class="actions step-links">${links.join('')}</div>`}
function plateSettings(){return `<details id="plate-settings" class="plate-settings"><summary>Plate layouts, individual STLs & settings</summary><div class="plate-settings-content">${plateSettingsHTML}</div></details>`}
function servoTable(){return `<section class="details"><h2>Servo channels</h2>${table(['Servo','BCM / physical pin','Level shifter terminal','Fit pose'],[['Robot-left shoulder','12 / 32','S1 C5','Arm hanging straight down'],['Robot-right shoulder','13 / 33','S2 D5','Arm hanging straight down'],['Head','16 / 36','S2 C5','Facing forward']],'cards')}<p class="fine">The fit pose is also the rest pose the application returns to when it starts. <a href="https://resources.kitronik.co.uk/pdf/25105-kitronik-clippable-servo-fs90mg-datasheet.pdf" target="_blank" rel="noreferrer">Kitronik FS90MG-CL servo datasheet ↗</a></p></section>`}
function commandCard(block){
 const kind=block.kind||'command',canCopy=kind!=='output'&&block.copy!==false;
 const context=kind==='command'?(block.context==='pi'?'On the Pi · SSH session':'On your computer'):kind==='config'?'File example':'Expected output';
 return `<div class="code-card" data-kind="${escape(kind)}"><div class="code-card-header"><div><span class="code-context">${context}</span>${block.label?`<strong class="code-label">${escape(block.label)}</strong>`:''}</div>${canCopy?`<button type="button" data-copy-code aria-label="Copy ${kind==='config'?'example':'command'}${block.label?' · '+escape(block.label):''}">Copy ${kind==='config'?'example':'command'}</button>`:''}</div><pre class="code-content" tabindex="0" aria-label="${escape(block.label||context)}"><code>${block.lines.map(escape).join('\n')}</code></pre>${canCopy?'<p class="copy-status" role="status" aria-live="polite" aria-atomic="true"></p>':''}</div>`;
}
function actionPanels(s){
 const panels=s.panels;
 return `<div class="action-sequence">${panels.map((panel,i)=>`<section class="action-panel${/^assets\/circuits\//.test(panel.image)?' action-panel-circuit':''}${/^assets\/setup\//.test(panel.image)?' action-panel-screenshot':''}${panel.image?'':' action-panel-command'}"><div class="action-panel-heading"><span aria-hidden="true">${i+1}</span><h2>${escape(panel.title)}</h2></div><div class="action-panel-body">${panel.image?diagram(panel.image,panel.title):''}<div class="action-copy"><ol class="instructions">${panel.actions.map(n=>`<li>${rich(s.actions[n])}</li>`).join('')}</ol>${(panel.codeBlocks||(panel.commands?.length?[{kind:'command',context:'computer',lines:panel.commands}]:[])).map(commandCard).join('')}${panel.caption?`<p class="action-note">${rich(panel.caption)}</p>`:''}${panel.links?.length?`<ul class="panel-links">${panel.links.map(link=>`<li><a href="${escape(link.url)}"${/^https:/.test(link.url)?' target="_blank" rel="noreferrer"':''}>${escape(link.label)}${/^https:/.test(link.url)?' ↗':''}</a></li>`).join('')}</ul>`:''}${panel.detail?`<details class="action-detail"><summary>${escape(panel.detail.title)}</summary>${diagram(panel.detail.image,panel.detail.title)}</details>`:''}</div></div></section>`).join('')}</div>`;
}
function stepHTML(s,all=false,partId){
 return `<article class="${[all?'full-print':'',s.id.startsWith('software-')?'setup-step':''].filter(Boolean).join(' ')}"><div class="step-head"><div><p class="eyebrow">${s.kind==='service'?'Service reference':escape(s.chapter)+' · Step '+s.number+' of '+buildSteps.length}</p><h1 tabindex="-1">${escape(s.title)}</h1></div>${s.number?`<span class="step-number" aria-hidden="true">${s.number}</span>`:''}</div>${s.id==='02'?printResources(partId):benchList(s)}${s.id==='light-input'?harnessOverview():''}${actionPanels(s)}${s.id==='02'?printTemplates():''}${s.note?`<div class="notice step-note">${rich(s.note)}</div>`:''}<div class="check"><strong>Ready to continue</strong>${rich(s.check)}</div>${stepTips(s)}${templates[s.id]?`<p><a class="button" href="${templates[s.id][0]}" download>${templates[s.id][1]}</a> Print at 100% and check the scale bar.</p>`:''}${s.id==='servo-position'?servoTable():''}${stepLinks(s)}${stepNavigation(s)}</article>`;
}

function start(){
 const next=buildSteps.find(s=>!state.steps.includes(s.id))||buildSteps[0];
 const started=buildSteps.some(s=>state.steps.includes(s.id));
 const features=[
  ['M4 5h16v11H9l-5 4V5Zm4 4h8m-8 3h5','A voice of his own','Ask a question, swap stories or follow a curious tangent. Press his button and talk with him in your own words.'],
  ['M5 9h14v11H5zM9 5h6M12 2v3M8 13h1m6 0h1M9 17h6M2 11v6m20-6v6','Personality you can see','His arms rotate up and down, and his head turns from side to side. Glowing eyes and body lights give this little character his own presence.'],
  ['M9 18V5l11-2v12M9 7l11-2M9 18c0 4-6 4-6 1s6-4 6-1m11-3c0 4-6 4-6 1s6-4 6-1','A tiny dance party','Ask him to dance and he plays music with coordinated movements. When the song finishes, he returns to the conversation.'],
  ['M12 12l7-7M12 4a8 8 0 1 0 8 8M12 8a4 4 0 1 0 4 4M12 12h.01','A Galactic Scanner','Curious about the weather or something happening on Earth? He can search the web, complete with a spaceship-style scanner sound.'],
  ['M9 2h6M12 2v3M18 6l2-2M12 10v5l3 2M12 6a8 8 0 1 0 0 16 8 8 0 0 0 0-16','A little everyday help','Set a named countdown timer, ask what is running or cancel it by name. He lets you know when time is up with sound and lights.'],
  ['M4 20l4-1L20 7l-3-3L5 16l-1 4Zm10-13 3 3M4 4h5M4 8h2','Your own kind of robot','Choose filament colors, add paint, and adjust his voice or personality. The hardware designs and software are open source, ready for tinkering.']
 ];
 return `<article class="character-intro"><div class="intro-grid"><section><p class="eyebrow">Hello, Earth.</p><h1 tabindex="-1">Meet<br>BlooglyBlob.</h1><p class="lede">A curious little visitor from planet Meep. He chats, lights up, waves his arms—and can even throw a little dance party.</p><p class="intro-copy">An open-source, 3D-printed robot you can build yourself. He runs on Raspberry Pi and uses the <a href="https://developers.openai.com/api/docs/models/gpt-live-1" target="_blank" rel="noreferrer">OpenAI Live API</a> for voice conversations.</p>${started?`<div class="actions"><a class="button primary" href="#step-${next.id}">Continue your build →</a></div>`:''}</section>${diagram('assets/r22/main-front.png','BlooglyBlob with blue-violet head and hands, copper details, ivory backpack and black enclosure').replace('loading="lazy"','loading="eager" fetchpriority="high"').replace('Enlarge diagram ↗','Take a closer look ↗')}</div>
 <section class="character-capabilities" aria-labelledby="character-features-title"><p class="eyebrow">Get to know him</p><h2 id="character-features-title">A few of his favorite things.</h2><div class="character-features">${features.map(([path,title,copy])=>`<section><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${path}"/></svg><h3>${title}</h3><p>${copy}</p></section>`).join('')}</div><div class="character-prompts"><span>Try saying</span><q>Tell me about space.</q><q>Let’s dance!</q><q>Set a five-minute timer.</q></div></section>
 <section class="character-build" aria-labelledby="character-build-title"><p class="eyebrow">Make a little character of your own</p><h2 id="character-build-title">Bring your BlooglyBlob to life.</h2><p>This is a hands-on build with 3D printing, soldering and Raspberry Pi setup. The guide takes you from loose parts to your first conversation.</p><div class="actions"><a class="button primary" href="#step-${next.id}">${started?'Continue your build':'Start building'} →</a><a class="button" href="#parts">Explore the parts</a></div><p class="fine">Voice features need an internet connection and your own OpenAI API key. API usage is billed to your account. <a href="#step-software-prepare">See the Pi setup steps</a>.</p>
 <p class="notice"><b>DIY project, provided as is.</b> You are responsible for your build and its use; no safety or performance guarantees are made. Children must work with and use the robot under direct adult supervision. <a href="#safety">Read the safety and responsibility notice</a>.</p>
 <details class="character-build-details"><summary>How the build works</summary><ol class="build-overview"><li><b>Prepare.</b> Gather tools and start printing. You can print in stages.</li><li><b>Build the base.</b> Fit vents, speakers and feet; mount the electronics and wire each circuit.</li><li><b>Build the character.</b> Add the frame, lights, head, arms and backpack.</li><li><b>Bring it to life.</b> Check the power, position all three servos, attach the head and arms, then test and close the base.</li></ol><p>You’ll use a soldering iron, a multimeter and a computer to set up the Raspberry Pi. Each step shows the parts, fasteners and action. Left and right mean the robot’s own sides.</p><p class="notice">Work unplugged unless a step explicitly calls for power. The front button starts a conversation; it does not turn the power off.</p><p><a href="#step-02">Print files & plates</a> · <a href="#notes">Materials & build notes</a></p></details>
 <details class="character-build-details"><summary>Jump to a chapter</summary><div class="chapter-grid">${[...new Set(buildSteps.map(s=>s.chapter))].map(c=>{const x=buildSteps.filter(s=>s.chapter===c);return `<a class="chapter-card" href="#step-${x[0].id}"><small>Steps ${x[0].number}–${x.at(-1).number}</small><b>${escape(c)}</b></a>`}).join('')}</div></details>
 <p class="fine">Your parts checklist and completed steps are saved in this browser’s local storage. They don’t sync between devices. <a href="references.html">Component datasheets</a></p></section></article>`;
}

function card(p){
 const media=p.image?`<button data-zoom="${escape(p.image)}" aria-label="Enlarge ${escape(p.name)} drawing" class="part-reference"><img loading="lazy" src="${escape(p.image)}" alt="${escape(p.name)}, drawing"></button>`:`<div class="no-image" aria-hidden="true">${p.id}</div>`;
 const buy=p.link?`<p><a href="${escape(p.link)}" ${p.link.startsWith('downloads/')?'download':'target="_blank" rel="noreferrer"'}>${p.link.startsWith('downloads/')?'Download STL':'View product ↗'}</a></p>`:p.category==='Printed'?'':'<p class="fine">Any part that meets the description above.</p>';
 const usedIn=p.steps.length?`<p class="fine">Used in: ${p.steps.map(id=>stepLink(id)).join(', ')}</p>`:'';
 const plate=p.category==='Printed'&&!p.omitted?(prints.some(pl=>pl.parts.includes(p.id))?`<p class="fine"><a href="#step-02/${p.id}">Which plate prints ${p.id}</a></p>`:'<p class="fine">Not on the supplied plates; print it from its STL if you want it.</p>'):'';
 return `<article class="part-card" id="part-${p.id}">${media}<div class="part-body"><span class="part-id">${p.id} / ${escape(p.category)}</span><h2>${escape(p.name)}</h2><span class="badge">${p.qty===0?'Optional: 1':typeof p.qty==='number'?p.qty+' '+(p.category==='Printed'?'to print':'needed'):escape(p.qty)}${p.optional&&p.qty!==0?` · ${escape(p.optional_label||'Optional')}`:''}</span><p>${rich(p.description)}</p>${p.category==='Printed'?'':`<p class="source-state">${escape(p.verification)}</p>`}${buy}${(p.additional_links||[]).map(a=>`<p><a href="${escape(a.url)}" ${a.url.startsWith('downloads/')?'download':'target="_blank" rel="noreferrer"'}>${escape(a.label)}${a.url.startsWith('downloads/')?'':' ↗'}</a></p>`).join('')}${usedIn}${plate}<label class="stock"><input type="checkbox" data-stock="${p.id}" ${state.stock.includes(p.id)?'checked':''}>${p.category==='Printed'?'Printed it':'Got it'}</label></div></article>`;
}
// Filters survive navigating to a step and back.
const partsFilter={q:'',c:'',stock:''};
function partsHTML(id){if(id==='tools'){id='';partsFilter.q='';partsFilter.c='Tool';partsFilter.stock='';}else if(partMap[id]){partsFilter.c='';partsFilter.stock='';}return `<p class="eyebrow">Parts for one robot</p><h1 tabindex="-1">Parts & supplies</h1><p class="lede">Everything needed for one robot. Search by name, part ID, product number or purpose. Quantities are what one robot uses; packs may contain more. Optional items are marked.</p><div class="notice info">Tick “Got it” or “Printed it” once you have the full quantity ready. Your checklist is saved in this browser only. Read the <a href="#notes">build notes</a> before shopping. Left and right mean the robot’s own sides. All white diffuser foam is 4 mm Plastazote LD45; the audio lid lining uses 1 mm foam (C10). Many parts have <a href="references.html">datasheets</a> you can open on the publisher’s site.</div><details class="stand-supplies"><summary>Materials for the optional service stand</summary>${standSupplies()}<p><a href="#step-fb-stand">Stand assembly instructions</a></p></details><div class="toolbar"><label class="sr-only" for="search">Search parts</label><input id="search" type="search" placeholder="Try “eye”, “M3”, “WAGO” or “AR01”" value="${escape(id||partsFilter.q)}" aria-label="Search parts"><select id="category" aria-label="Filter part category"><option value="">All categories</option>${['Printed','Purchased','Fastener','Consumable','Tool'].map(x=>`<option${partsFilter.c===x?' selected':''}>${x}</option>`).join('')}</select><select id="stock-filter" aria-label="Filter your checklist"><option value="">Everything</option><option value="missing"${partsFilter.stock==='missing'?' selected':''}>Still to get or print</option><option value="owned"${partsFilter.stock==='owned'?' selected':''}>Ready</option></select></div><p id="result-count" class="fine" aria-live="polite"></p><div id="parts-list" class="parts-grid"></div>`}
function filterParts(){const q=$('#search').value.toLowerCase().trim(),c=$('#category').value,stock=$('#stock-filter').value;if(!/^[a-z0-9]+$/i.test(q)||!partMap[q.toUpperCase()])partsFilter.q=$('#search').value;partsFilter.c=c;partsFilter.stock=stock;const listed=parts.filter(p=>!p.omitted);const exact=listed.find(p=>p.id.toLowerCase()===q);const found=listed.filter(p=>(!exact||p===exact)&&(!c||p.category===c)&&(!q||[p.id,p.name,p.description].join(' ').toLowerCase().includes(q))&&(!stock||(stock==='owned')===state.stock.includes(p.id)));$('#result-count').textContent=`Showing ${found.length} of ${listed.length}`;$('#parts-list').innerHTML=found.length?found.map(card).join(''):'<p class="empty">No matching parts. Try a shorter search or clear the filters.</p>'}
function hardware(){const rows=Object.entries(guide.totals).map(([id,n])=>[escape(partMap[id]?.name||id),n,guide.steps.filter(s=>s.hardware[id]).map(s=>`${stepLink(s.id)}: ${s.hardware[id]}`).join(' · ')]);return `<p class="eyebrow">Pick the right screw</p><h1 tabindex="-1">Fasteners & actual-size screw key</h1><p class="lede">The build uses ${Object.entries(guide.totals).filter(([id])=>id.startsWith('M2x')).reduce((n,[,q])=>n+q,0)} M2 screws, ${Object.entries(guide.totals).filter(([id])=>id.startsWith('M3x')).reduce((n,[,q])=>n+q,0)} M3 screws and the ${guide.totals.CENTER} center screws supplied with the servos. Each row lists one fastener and how many each step uses.</p><div class="downloads"><div class="download-card"><b>US Letter</b><a class="button primary" href="downloads/screw-key-letter.pdf" download>Download Letter PDF</a></div><div class="download-card"><b>A4</b><a class="button primary" href="downloads/screw-key-a4.pdf" download>Download A4 PDF</a></div></div><div class="notice"><b>Print at 100% (actual size).</b> Turn off “Fit”, “Shrink” and “Scale to page”, then measure the printed 50 mm ruler and 20 mm square before matching screws. Don’t match screws against a screen.</div><h2>Measuring screws</h2><p>Measure a screw from under its head to the tip; a countersunk screw is measured including its head. M2 and M3 are the thread diameters. Keep each servo center screw with its horn, apart from your M2 stock: its size isn’t specified.</p><p>Use standard hex nuts. The three head screws are M2×8 button heads, with no washers or plugs; the M2 kit in the parts list includes them. They’re designed for Ø3.5 × 1.3 mm heads in Ø4.0 × 1.55 mm recesses, so measure yours and test-fit them. Other M2 heads must fit within Ø3.8 × 2 mm and M3 socket heads within Ø5.5 × 3 mm; the countersunk screws have a Ø6 mm, 90° head. Stop tightening once a joint holds without bending the print.</p>${table(['Fastener','Quantity','Used in (step: quantity)'],rows)}<h2>Washers</h2><p>The eyes use four thin metal M2 washers. The speakers use eight M3 washers, about 0.5 mm thick; check them against your speaker tabs.</p><h2>Joints that are easy to mix up</h2><ul class="reader-list"><li>Head GS20 to shelf P08: three M2×8 button-head screws and M2 nuts, no washers.</li><li>Horn adapter P14 to shelf P08: three M3×8 screws and M3 nuts.</li><li>Lower collar to base: two M3×16 screws.</li><li>Level shifters on their enclosure posts: four M2×10 screws.</li><li>Front grille: four M3×6 screws and M3 nuts, without washers. Rear vent: four M3×12 screws and M3 nuts.</li><li>Bottom cover: four M3×12 screws.</li><li>WAGOs mount with double-sided tape; they use no mounting screws or nuts.</li></ul>`}

function printResources(partId){
 const match=partMap[partId],selected=match?prints.filter(p=>p.parts.includes(partId)):[];
 const context=match?`<p class="notice info">${escape(partId)} · ${escape(match.name)}: ${selected.length?selected.map(p=>escape(p.name)).join(', '):'not on the supplied plates'}. <a href="#step-02">Show the full printing step</a></p>`:'';
 return `<p class="lede">${printedPieceCount} printed pieces / ${parts.filter(p=>p.category==='Printed'&&p.qty>0).length} types on ten PLA plates. Start with the enclosure and vents, then print the rest as you build.</p>
 <div class="actions"><a class="button primary" href="downloads/BlooglyBlob-PLA.3mf" download>Bambu project · all plates</a><a class="button" href="downloads/BlooglyBlob-STL.zip" download>All STL files (ZIP)</a><a class="button" href="downloads/BlooglyBlob-PETG-ball.3mf" download>Optional PETG ball</a></div>
 <p class="fine">Choose your own colors. Print one antenna ball: PLA on plate 10 or the optional clear PETG version. For STLs, use the settings and orientations below in your own slicer.</p>
 ${context}${plateSettings()}
 <p class="fine">Optional pointing hand: <a href="downloads/stl/AR07.stl" download>AR07 STL</a> · print fingers up, wrist peg down.</p>`;
}
function printTemplates(){return `<details><summary>Cutting templates & service stand</summary><p><a href="downloads/eye-film-template.pdf" download>Eye film (PDF)</a> · <a href="downloads/eye-film-template.svg" download>Eye film (SVG)</a> · <a href="downloads/body-foam-template.svg" download>Body foam (SVG)</a> · <a href="downloads/service-stand-template.svg" download>Wooden stand template (SVG)</a> · <a href="downloads/service-stand.dxf" download>Stand (DXF)</a> · <a href="downloads/service-stand-saddle-J05.stl" download>Optional stand saddle J05 (STL)</a>. Print templates at 100% and check the scale bar.</p></details>`;}

function harnessOverview(){return `<section class="harness-overview action-panel-circuit"><h2>What connects between assemblies</h2><div class="action-panel-body">${diagram('assets/circuits/harness-connections.svg','BASE to BODY and HEAD lighting use three-pin JST-SM plugs; each servo has bare power, ground and signal ends for its terminals.')}<div class="action-copy"><p>Lighting data travels from the enclosure → six body lights → two eyes → eight mouth LEDs. Head power uses a separate 22 AWG pair branched before the body lights.</p><p>Leave a relaxed loop for head rotation and enough slack to lift the head and unplug HEAD. The servo cables stay on the stationary frame. Dry-route before final trimming; keep both lighting latches and the servo terminals reachable.</p></div></div></section>`}
function referenceFigures(label,figures){return `<div class="reference-gallery" aria-label="${label}">${figures.map(([file,title])=>diagram(file,title)).join('')}</div>`}
function masterWiring(){return `<details class="reference-topic" id="reference-master" open><summary>Master wiring diagram</summary><div class="reference-content">
 <p>Follow each wire between the components. Dots mark joins; crossings without a dot stay separate. Pi labels are physical header pin numbers.</p>
 <div class="master-tools" aria-label="Master diagram view"><button data-wiring-detail aria-pressed="false">Larger labels</button><a href="assets/circuits/master-wiring.svg" target="_blank" rel="noreferrer">Open full-size SVG ↗</a><a href="assets/circuits/master-wiring.svg" download>Download SVG</a></div>
 <figure class="master-wiring"><div class="master-window" tabindex="0" role="region" aria-label="Master wiring diagram; scroll to follow connections" aria-describedby="master-help"><img src="assets/circuits/master-wiring.svg" width="2640" height="2120" alt="One connected master wiring diagram: inlet and Pi supply, WAGO ports, fuses and capacitors, all twelve Pi header connections, three servos, button, USB audio and the sixteen-pixel lighting chain. Every component appears once, with continuous wires between its terminals and the next component."></div><figcaption id="master-help">The whole circuit is shown together. Use Larger labels to zoom and scroll. Positions and connector contact order are schematic; use the assembly steps for physical placement and close-ups.</figcaption></figure>
 </div></details>`}
function electricalHTML(){return `<article class="electrical-reference"><p class="eyebrow">Wiring lookup</p><h1 tabindex="-1">Electrical reference</h1><p class="lede">Start with the complete wiring map. Choose a topic for terminal tables and close-ups.</p>
 <nav class="reference-picker" aria-label="Electrical topics">${[
 ['power','Power & WAGO','Supply, fuses and port numbers','assets/cartoons/E06.svg'],
 ['signals','Pi & button','Header pins and level shifters','assets/cartoons/E15.svg'],
 ['lights','Lights','Body → eyes → mouth','assets/cartoons/E03.svg'],
 ['connectors','Plugs & servos','Connections between assemblies','assets/cartoons/E10.svg']
 ].map(([id,title,note,src])=>`<button data-reference="${id}" aria-controls="reference-${id}" aria-expanded="false"><img src="${src}" alt=""><span><b>${title}</b><small>${note}</small></span></button>`).join('')}</nav>
 <div class="reference-shortcuts"><button data-reference="master" aria-controls="reference-master" aria-expanded="true">Master wiring diagram</button><button data-reference="layout" aria-controls="reference-layout" aria-expanded="false">Layout & cable routes</button><button data-reference="routing" aria-controls="reference-routing" aria-expanded="false">Wire lengths & insulation</button><button data-reference="tests" aria-controls="reference-tests" aria-expanded="false">Assembly checks</button><button data-reference="names" aria-controls="reference-names" aria-expanded="false">Circuit labels & datasheets</button></div><p class="reference-safety">Check wiring with power disconnected. Follow the staged tests before fitting the head and arms; the first strand test keeps F1 removed.</p>
 ${masterWiring()}
 <details class="reference-topic" id="reference-layout"><summary>Find the components in the enclosure</summary><div class="reference-content">${referenceFigures('Physical component locations',[['assets/community/base-electrical-layout.svg','Open-bottom layout: USB front, SD rear; S1 nearer Pi, S2 nearer audio'],['assets/community/wago-port-order.svg','WAGO ports: 1 on the right in this open-bottom view']])}<p>View through the open bottom. WAGO wire entries face the front; their levers face you. Match the connector labels, not their order in a wiring diagram.</p>${referenceFigures('Cable routing examples',[['assets/community/pi-power-route-depth.svg','Short H2 power lead to W1/2 and W3/2'],['assets/community/usb-audio-route-depth.svg','USB route below the audio cradle']])}<p>Routing examples show these two cables only. Dry-fit your actual leads before trimming, keep H2 at 150 mm or less including its plug, and check that the cover closes without pressing on a cable.</p></div></details>
 <details class="reference-topic" id="reference-power"><summary>Power & WAGO terminals</summary><div class="reference-content">
 <div class="reference-pair">${diagram('assets/power-diagram.svg','Power distribution: Pi, servo and lighting branches')}<div>
 <p><b>Supply:</b> Mean Well GST40A05-P1J, 5 V / 5 A.</p><p><b>F1 · servos:</b> T3.15 A.<br><b>F2 · lights:</b> T1 A.</p>
 <p>W2/3 means WAGO W2, port 3. Number ports from the robot’s right. All five ports in one block are electrically joined.</p>
 <ul class="reference-notes"><li>W1 reaches W2 only through F1. Join W3 to W4 with 18 AWG wire.</li><li>One untinned wire per port. Speaker outputs never connect to these ground blocks.</li><li>H2 and the wiring before the fuses rely on the specified supply’s overload shutdown; do not substitute a higher-current supply.</li></ul></div></div>
 <h3>Find your WAGO port</h3>
 ${referenceFigures('WAGO port diagrams',[['assets/circuits/w1-reference.svg','W1 port assignments'],['assets/circuits/w3-reference.svg','W3 port assignments'],['assets/circuits/w2-reference.svg','W2 port assignments'],['assets/circuits/w4-reference.svg','W4 port assignments']])}
 <details class="reference-table"><summary>All power connections as a table</summary>${table(electrical.power.header,electrical.power.rows,'cards')}</details>
 <p class="reference-build">Assembly: ${S('fb-power')} · ${S('fb-servo-power')} · ${S('fb-light-power')}</p></div></details>
 <details class="reference-topic" id="reference-signals"><summary>Pi pins, level shifters & button</summary><div class="reference-content">
 <p>Use <b>physical header pin numbers</b>. Button light: pin 4 (+5 V) → R1 (1 kΩ) → LED +; pin 20 (GND) → LED −. Its separate switch uses pin 11 (GPIO17) and pin 14 (GND).</p>
 <p>S1 and S2 shift signals from 3.3 V to 5 V; they do not power the servos or lights. Leave !D5 outputs unused. Cut the <a href="https://learn.adafruit.com/adafruit-pixel-shifter/pinouts" target="_blank" rel="noreferrer">Neo jumper</a> on both S1 and S2 to disable their onboard test LEDs; both signal channels remain active.</p>
 ${referenceFigures('Show Pi and button connections',[['assets/circuits/s1-inputs.svg','Pi to S1'],['assets/circuits/s2-inputs.svg','Pi to S2'],['assets/circuits/button-switch.svg','Button switch'],['assets/circuits/button-led.svg','Button light: power and ground']])}
 <details class="reference-table"><summary>All Pi and signal connections as a table</summary>${table(electrical.signal.header,electrical.signal.rows,'cards')}</details>
 <p class="reference-build">Assembly: ${S('fb-boards')} · ${S('fb-inlet-button')} · ${S('fb-signals')}</p></div></details>
 <details class="reference-topic" id="reference-lights"><summary>Lighting: data order & power branches</summary><div class="reference-content">
 <p><b>Data:</b> GPIO18 → S1 DAT / D5 → R2 (330 Ω) → body lights 0–5 → HEAD → eyes 6–7 → mouth 8–15. Each DOUT connects to the next DIN.</p>
 <p><b>Power:</b> F2 and C2 feed H3. At the body input, +5 V and GND split between the strand and a separate 22 AWG HEAD pair. In the head, power splits to the first eye and directly to the mouth. The eye-to-eye cable powers the second eye. Insulate the unused strand power wires after light 5.</p>
 <p>16 pixels · GRB order · brightness 128/255. The test lights all 16; normal use animates the body and eyes, with the mouth off.</p>
 ${referenceFigures('Show the lighting connections',[['assets/circuits/body-power.svg','Dedicated head power branches'],['assets/circuits/body-output.svg','Body light 5 to HEAD'],['assets/circuits/head-power.svg','Eye and mouth power'],['assets/circuits/head-data.svg','Eye and mouth data']])}
 <p class="reference-build">Assembly: ${S('light-input')} · ${S('12')} · ${S('14')}</p></div></details>
 <details class="reference-topic" id="reference-connectors"><summary>Plugs, servo terminals & service slack</summary><div class="reference-content">
 <div class="reference-pair">${diagram('assets/circuits/harness-connections.svg','Two JST-SM lighting plugs; servo wires land directly in terminals')}<div><p><b>BASE→BODY:</b> H3 stays with the enclosure; its mate stays with the body.</p><p><b>HEAD lighting:</b> one half stays with the body, the other with the head. Both lighting plugs carry +5 V, GND and DATA.</p><p>Eyes use JST-SH plugs. Mouth and body-strand joints are soldered.</p><p>Leave a relaxed loop for head rotation and lifting the head to unplug it. Servo cases stay on the frame; their cables need service slack, clear of horns. Label both ends and keep plugs and terminals reachable.</p></div></div>
 ${table(['Servo','Power / ground','Signal'],[['Left shoulder','W2/2 · W4/2','S1 C5'],['Right shoulder','W2/3 · W4/3','S2 D5'],['Head','W2/4 · W4/4','S2 C5']],'cards')}
 <p class="reference-build">Routing: ${S('13')} · ${S('33')}. Replacement: ${S('fb-servo-service')}.</p></div></details>
 <details class="reference-topic" id="reference-routing"><summary>Wire lengths, routing & insulation</summary><div class="reference-content">
 ${table(['Item','Requirement'],[['H2 Pi power','24 AWG; plug and lead together ≤150 mm. No extension. Release its tie to unplug.'],['Fuse holders','Dry-route the loop before cutting. Input reaches without extension; any output extension is 18 AWG, soldered and insulated on the bench.'],['C1 / C2','1000 µF, 10 V. Stripe is negative. Insulate each lead from the rubber-seal end separately; leave the opposite vent end clear.'],['Bundle supports','Anchor to the enclosure with adhesive tie mounts. Support component bodies independently of wires; keep fuse openings accessible.'],['Clearance','At least 4 mm from wiring and tie locks to the cover. Keep the central hole smooth and the SD card, body screws and moving parts clear.']],'cards')}
 <p>No wiring attaches to the bottom cover. Dry-route your build before final trimming.</p><p class="reference-build">Assembly: ${S('fb-fuses-capacitors')} · ${S('33')}</p></div></details>
 <details class="reference-topic" id="reference-tests"><summary>Assembly checks & expected results</summary><div class="reference-content">
 ${table(['Stage','Check / expected result'],[[`${S('fb-base-check')} and ${S('34')} · unpowered`,'Jack and capacitor polarity, fuses, isolated W1/W2, correct Pi pins, insulated wiring; no speaker-to-ground connection.'],[`${S('light-input')} · strand input`,'Uncut strand; F1 removed and servos disconnected. Mark INPUT only after a positive light test.'],[`${S('35')} · all 16 lights`,'All 16 lights in order with correct colors; Pi starts without a power warning. Head and arms still off.'],[`${S('servo-position')} and ${S('first-motion')}`,'Set the fit pose, attach parts, then check movement and cable slack.'],[`${S('system-check')} · before closing`,'Plugs and WAGO levers seated, joints insulated, wires secured clear of the cover.'],[`${S('fb-closed-test')} · closed enclosure`,'Try conversation, sound, movement and lighting with the cover fitted.']],'cards')}
 </div></details>
 <details class="reference-topic" id="reference-names"><summary>Circuit names & component documents</summary><div class="reference-content">
 <p>Circuit labels differ from parts-list IDs: C1 is a capacitor, not consumable C01.</p>
 ${table(['Label','Component'],[['J1 / H2 / H3','Power inlet / Pi power lead / enclosure half of BASE→BODY'],['W1–W4','WAGO connectors (E06)'],['F1 / F2','Servo / lighting fuses, in E07 holders'],['C1 / C2','Servo / lighting capacitors (E08)'],['S1 / S2','Level shifters (E15)'],['R1 / R2','1 kΩ button-light resistor / 330 Ω lighting-data resistor']],'cards')}
 <p><a href="references.html">Open component datasheets</a></p></div></details></article>`}
function troubleshooting(){return `<p class="eyebrow">Find and fix a problem</p><h1 tabindex="-1">Troubleshooting</h1><p>Shut down the Pi and unplug the power supply before changing any connection. The front button doesn’t switch the power off.</p>
 <h2>Assembly and wiring</h2>${table(['Problem','Check first','Then'],[['A joint stays loose','The nut is seated, the screw is the right length, and the print and threads are undamaged.','Compare the step’s hardware list with the screw key.'],['The head or an arm won’t seat','Horn orientation, the drilled horn holes, the bracket screws and cables.','Go back to the assembly step. Don’t force a servo shaft round to make it fit.'],['The head or an arm is off its pose, touches something or strains',`Which spline tooth it’s on, the cable slack and clearance.`,`Unplug, then refit it in the fit pose (${S('servo-position')}), one tooth closer.`],['An eye or the mouth doesn’t fit','Leftover support, film and foam thickness, washers and screw length.',`See ${S('37')}. The mouth wires are soldered, so don’t pull the cassette by them.`],['Lights are dark or the wrong color','The mouth stays off during normal use; check it with the light test. For lights that fail the test, check power, ground and data, the strand’s input end, and resistor R2.','Run <code>make pi-test-neopixels</code>. If a light stays dark during its turn, check the join just before it.'],['A fuse blows','A short, reversed polarity, the load, and the exact time-delay fuse value.','Fix the cause. Never bypass a fuse or fit a larger one.'],['Audio rattles or feeds back','Clear openings, a firmly held module, secure speaker mounts and separate speaker pairs.','Repeat the sound checks in '+S('fb-closed-test')+'.'],['The bottom cover won’t seat','A wire, splice or tie sticking into the cover space; a trapped edge; a warped print.','Reroute the obstruction. Never pull the cover down with its screws.'],['A base part is hard to remove','Nearby ties, terminal access and wire slack.','Release its connections as described in '+S('fb-service')+'.']])}
 <h2>Software</h2>${table(['Problem','Check first','Then'],[['<code>make pi-check</code> rejects the Pi','It needs a Raspberry Pi 3 running Raspberry Pi OS Lite 64-bit (Trixie, Python 3.13).','Rewrite the card with Raspberry Pi Imager; see <a href="#software">Software</a>.'],['“Could not resolve hostname” or the connection times out','The Pi is powered and on your Wi-Fi; <code>PI_HOST</code> in <code>.env</code> matches its hostname.','Use the Pi’s IP address from your router’s device list instead of the <code>.local</code> name.'],['“Permission denied (publickey)”','Your public key was added in Imager, and <code>PI_USER</code> matches the username you chose.','Rewrite the card with your key, or add it to the Pi’s <code>~/.ssh/authorized_keys</code>.'],['“REMOTE HOST IDENTIFICATION HAS CHANGED”','Did you just rewrite the card? If not, stop: you may be connecting to a different device.','After confirming the hostname/IP belongs to your newly imaged Pi and verifying its new host key, remove the old entry with <code>ssh-keygen -R &lt;your-host&gt;</code>, then reconnect.'],['Provisioning stops because the built-in audio is loaded','This is expected on the first run.','Run <code>make pi-ssh</code>, then <code>sudo reboot</code>. When SSH works again, rerun <code>make pi-provision</code>.'],['“OPENAI_API_KEY is required in app.env”','Your key is in <code>config/app.env</code> (first install) or <code>/etc/blooglyblob/app.env</code> (after that).','Add the key and rerun provisioning, or edit the Pi’s copy and run <code>make pi-restart</code>.'],['“AUDIO_INPUT_DEVICE must identify one available audio device”','The audio module’s USB lead is plugged in, and the name you set matches what <code>cat /proc/asound/cards</code> shows after “USB-Audio - ”.','Correct both audio names in <code>/etc/blooglyblob/app.env</code> with <code>sudoedit</code>, then <code>make pi-restart</code>.'],['The application isn’t running','<code>make pi-status</code>, then <code>make pi-logs</code> (Ctrl+C to return).','Fix what the log reports, then <code>make pi-restart</code>. After some errors it stays stopped on purpose until you restart it.'],['It answers with an error or not at all','In <code>make pi-logs</code>: 401 means a wrong key, 429 a rate, credit or usage limit (read the error for its cause), and “model not found” an account without access to that model.','Check the key, billing and limits at platform.openai.com. The robot needs internet access.'],['No sound or the microphone doesn’t pick up','The speaker plugs and the USB lead.','Run <code>make pi-test-audio</code> (test tone) and <code>make pi-test-mic</code> (record and play back).'],['<code>vcgencmd get_throttled</code> isn’t <code>throttled=0x0</code>','This is a bitmask: 0x1 means undervoltage now and 0x10000 means it occurred since boot. 0x8 means the soft temperature limit is active and 0x80000 means it occurred since boot. Frequency-capping and throttling flags can accompany either condition.','Low voltage: check the supply, the H2 lead length and its plug. Heat: keep the vents and feet clear. To read the processor temperature, run <code>make pi-ssh</code>, then <code>vcgencmd measure_temp</code>; type <code>exit</code> afterward. See the <a href="https://www.raspberrypi.com/documentation/computers/os.html#get_throttled">official flag table</a>.']])}
 <div class="actions"><a class="button" href="#step-37">Head and arm service</a><a class="button" href="#step-fb-service">Open the base</a><a class="button" href="#step-fb-stand">Service stand</a></div>`}

function notesHTML(){return `<p class="eyebrow">Build notes</p><h1 tabindex="-1">What to know before you build</h1><p class="lede">Materials to choose, the words this guide uses and how to read its drawings.</p>
 <h2>Materials</h2><ul class="reader-list"><li>Eye, mouth and body diffusers: <a href="https://coscomcosplaysupplies.com/products/plastazote-ld45">white Plastazote LD45, 4 mm thick</a>. The shop sells other thicknesses too, so choose 4 mm.</li><li>Eye windows: any clear, flexible transparency sheet that lies flat in the groove without forcing the lip. Cut them with the full-size template.</li><li>Audio lid lining: nonconductive closed-cell foam, 1 mm thick (C10). WAGOs and the audio case use double-sided tape (C16); the audio patch must be under 1 mm thick. Base wiring also uses 1-inch adhesive tie squares (C17); retain the nuts with two-part epoxy (C09), or optional CA gel (C18). Clean and dry the bonding surfaces, follow the adhesive maker’s preparation and bonding time, then check the bond before loading it.</li><li>Fuses: use the specified values and series. A fuse doesn’t stop a servo at the end of its travel, and it isn’t a precise current limit.</li><li>Fit: dry-fit the eye nuts and screws, speaker tabs, the button insert, the servo horns and the wrists with your own parts before fastening or gluing.</li></ul>
 <h2>Words used in this guide</h2><dl class="glossary">${[['Robot-left / robot-right','The robot’s own sides. Robot-left is on your right when you face it.'],['AWG','American wire gauge. A smaller number is a thicker wire: 18 AWG carries power, 22–24 AWG signals and lighting.'],['GPIO, BCM and pin numbers','The Pi’s 40-pin header. Pin numbers (1–40) are positions on the header; BCM numbers (such as BCM18) are the software names of the signals.'],['Level shifter (S1, S2)','An Adafruit Pixel Shifter board. It turns the Pi’s 3.3 V signals into the 5 V signals the servos and lights expect.'],['WAGO (W1–W4)','A lever connector: open a lever, push a stripped wire in, close the lever. All five ports on one WAGO are connected.'],['Time-delay fuse (T)','A fuse that tolerates short surges, such as servos starting, but blows on a lasting overload. T3.15 A means time-delay, 3.15 A.'],['JST-SM, JST-SH','Small latching plugs. JST-SM joins wires (the BASE→BODY and HEAD plugs); JST-SH is the tiny 1 mm socket on the eye boards.'],['Light numbers 0–15','The position of each light in the data chain: body 0–5, eyes 6–7, mouth 8–15. Each light passes data from its DIN (data in) to its DOUT (data out).'],['Pebble','One light on the body strand: a small LED sealed in a resin bead.'],['Horn and spline','The horn is the round disc that fits the servo’s toothed (splined) shaft. The spline has 21 teeth, so a horn can only sit in 21 positions.'],['Fit pose and rest pose','Head facing forward and arms hanging straight down. You attach the head and arms in this pose, and the robot returns to it whenever the application starts.'],['PLA, PETG','The two filaments used. Everything is PLA; the antenna ball can optionally be clear PETG.'],['AMS','Bambu’s automatic material system for loading several filaments.'],['Service stand','A small wooden stand that holds the robot on its left side while you work on the base.']].map(([t,d])=>`<dt>${escape(t)}</dt><dd>${escape(d)}</dd>`).join('')}</dl>
 <h2>Reading the drawings</h2><p>The CAD views show the real part shapes in the robot’s orientation. The black enclosure is drawn in a lighter color so its inside features are visible. Lines point to parts; arrows show insertion or removal direction where labeled. In fastener views, circles mark screw seats and squares mark nuts. Diagrams that aren’t to scale are labeled.</p>
 <div class="actions"><a class="button primary" href="references.html">Datasheets</a><button id="all-steps">Show all steps for printing</button></div>
 <h2>Credits</h2><p>Renders of the Adafruit boards use Adafruit’s 3D models (Limor Fried/Ladyada, Adafruit Industries), shared under <a href="https://creativecommons.org/licenses/by-sa/3.0/" target="_blank" rel="noreferrer">Creative Commons Attribution-ShareAlike</a>; see <a href="https://github.com/adafruit/Adafruit_CAD_Parts" target="_blank" rel="noreferrer">Adafruit CAD Parts</a>. The <a href="references.html">datasheets page</a> links to the publishers’ documents; internet access is required. Product names and part numbers belong to their manufacturers.</p><p>Project source: <a href="${REPO}" target="_blank" rel="noreferrer">${REPO.replace('https://','')}</a>.</p>`}

const softwareTopics=['overview','commands','settings','troubleshooting'];
function software(topic){
 const cmd=(line,label,context='computer')=>commandCard({kind:'command',context,label,lines:[line]});
 const lookup=(line,label,description)=>`<section class="software-command">${cmd(line,label)}<p>${description}</p></section>`;
 return `<article class="software-reference"><p class="eyebrow">Keep this page handy</p><h1 tabindex="-1">Software reference</h1><p class="lede">Commands, settings and help for the application running on your Pi.</p><div class="setup-cta"><div><strong>First time setting up the Pi?</strong><p>Follow the four setup steps before mounting it in the base.</p></div><a class="button primary" href="#step-software-prepare">Start Pi setup →</a></div>
 <nav class="software-topic-nav" aria-label="Software topics">${softwareTopics.map(id=>`<a href="#software/${id}"${topic===id?' aria-current="location"':''}>${{overview:'How it works',commands:'Commands',settings:'Settings',troubleshooting:'Troubleshooting'}[id]}</a>`).join('')}</nav>
 <section id="software-overview" class="software-section"><h2 tabindex="-1">How it works</h2><div class="software-overview"><div><p>One application runs on the Raspberry Pi, managed by <code>blooglyblob.service</code>. It handles the button, microphone, speakers, lights and servos, and uses OpenAI over the internet for conversation. Your computer is needed for setup and updates.</p><p>During a conversation, microphone audio streams to OpenAI. Conversations can also open for alert acknowledgements or resume after a dance.</p><p>The application starts on boot. Press the front button to start a conversation; the button does not turn power off. Starting the application moves the servos to their rest pose and may make a billable speech request to prepare its greeting.</p></div>${diagram('assets/community/software.svg','The single Pi application and its connections')}</div></section>
 <section id="software-commands" class="software-section"><h2 tabindex="-1">Commands</h2><p>Run computer commands from the repository folder. On Windows, use the same WSL environment and SSH key you used during setup.</p><h3>Status and logs</h3><div class="software-command-grid">${lookup('make pi-status','Application status','Shows whether the service is running. This does not test the microphone, wiring or physical build.')}${lookup('make pi-logs','Follow the log','Press Ctrl+C to stop following the log and return to your computer’s prompt. The service keeps running.')}</div>
 <h3>Start and stop</h3><p>Starting or restarting moves the head and arms to their rest pose. Keep the mechanism clear.</p><div class="software-command-grid">${lookup('make pi-start','Start the application','Starts the installed service.')}${lookup('make pi-stop','Stop the application','Stops the service. The Pi stays powered.')}${lookup('make pi-restart','Restart the application','Use after changing the installed settings.')}</div>
 <h3>Update the application</h3><p>Get the latest repository code, then install it. An update restarts the service and preserves the Pi’s settings.</p><div class="software-command-grid">${cmd('git pull','Get the current code')}${cmd('make pi-update','Install the update')}</div><p>If it reports missing system prerequisites, follow the repair message and run <code>make pi-provision</code>. First installation is covered in ${S('software-install')}.</p>
 <h3>Connect or shut down</h3>${cmd('make pi-ssh','Open an SSH session')}<p>In that Pi session, use <code>exit</code> to return to your computer, or shut down before disconnecting power:</p>${cmd('sudo poweroff','Shut down the Pi','pi')}<p>Wait for shutdown and for the green activity light to stop flashing before unplugging the supply.</p>
 <details class="software-tests"><summary>Hardware checks and servo fitting</summary><p>Use these after installation, with the matching hardware ready. Follow the relevant assembly step before running a physical test.</p><div class="software-command-grid">${lookup('make pi-check-audio','List audio devices','Lists devices without recording. It temporarily stops the application and restores it afterward if it was running.')}${lookup('make pi-test-audio','Play a test tone','Uses the configured speaker output; keep the volume comfortable.')}${lookup('make pi-test-mic','Record and play back','Records a short microphone sample, then plays it back.')}${lookup('make pi-test-neopixels','Test the lights',`Follow ${S('35')}. Lights each of the 16 lights in turn and runs color patterns.`)}${lookup('make pi-servo-fit','Hold the servo fit pose',`Follow ${S('servo-position')} with the head and arms off their shafts. Type STOP when instructed. This command leaves the application stopped.`)}</div><p>Audio and light checks restore the service afterward if it was running, which can move the servos. Run <code>make pi-stop</code> first when it must stay stopped. Servo fitting always leaves it stopped.</p></details></section>
 <section id="software-settings" class="software-section"><h2 tabindex="-1">Settings</h2>${table(['File','Purpose'],[['<code>.env</code> on your computer','Selects PI_HOST, PI_USER and the initial configuration file. These choose where deployment commands connect.'],['<code>config/app.env</code> on your computer','Private input for the first provisioning: OpenAI key, audio selection and optional integrations. Never commit or share it.'],['<code>/etc/blooglyblob/app.env</code> on the Pi','The installed application’s settings. Existing remote settings take precedence on subsequent provisioning and updates.']],'cards')}<p>To change an installed setting, open an SSH session, edit the Pi’s file, then leave SSH before restarting from your computer:</p>${cmd('make pi-ssh','Connect from your computer')}${cmd('sudoedit /etc/blooglyblob/app.env','Edit installed settings','pi')}${cmd('exit','Return to your computer','pi')}${cmd('make pi-restart','Apply the change')}
 <details><summary>Configuration names</summary>${table(['Setting','Purpose'],[['AUDIO_INPUT_DEVICE / AUDIO_OUTPUT_DEVICE','Unambiguous device-name fragments. A missing or ambiguous selected device prevents startup.'],['OPENAI_API_KEY','Your private API credential. API usage is billed separately from ChatGPT.'],['OPENAI_LIVE_MODEL / OPENAI_RESPONSES_MODEL / OPENAI_SPEECH_MODEL','Models for conversation, answers/actions and prepared speech. Your API account must have access to them.'],['OPENAI_VOICE / OPENAI_SPEECH_VOICE','Conversation voice and prepared-speech voice.'],['MIC_GAIN','Software microphone amplification, not speaker volume. Set 1 for no added amplification; tune after a voice test.'],['OPENAI_INACTIVITY_SECONDS / OPENAI_SESSION_MAX_SECONDS','Conversation inactivity and maximum duration limits.'],['TMDB_API_KEY / WATCHMODE_API_KEY / ROKU_IP / RING_TOKEN','Optional integrations; see the repository documentation.']].map(([key,value])=>[`<code>${key}</code>`,value]),'cards')}<p><a href="${REPO}/blob/main/config/app.env.example" target="_blank" rel="noreferrer">Current configuration example ↗</a></p></details></section>
 <section id="software-troubleshooting" class="software-section"><h2 tabindex="-1">Troubleshooting</h2><dl class="software-help"><dt>SSH cannot find the Pi</dt><dd>Check Wi-Fi and the recorded hostname/username. Try the Pi’s IP address from your router’s device list, then update PI_HOST. After reimaging, verify the destination before resolving a host-key warning.</dd><dt>The OS check fails</dt><dd>The installer requires Raspberry Pi 3, 64-bit Raspberry Pi OS Lite Trixie and Python 3.13. Return to ${S('software-prepare')} to check your image.</dd><dt>Provisioning asks for a reboot</dt><dd>If it reports loaded onboard analogue audio, reboot and rerun the same provisioning command as shown in ${S('software-install')}. The GPIO18 light driver cannot share PWM with that audio driver.</dd><dt>The application does not start</dt><dd>Read <code>make pi-status</code> and <code>make pi-logs</code>. Check the installed settings, API access and connected USB audio device. Repair the reported cause; updates do not replace your installed settings.</dd><dt>Adjust speaker volume</dt><dd>Use the USB module’s ALSA Speaker control, starting at −40 dB; see ${S('software-configure')}. Save changes with <code>sudo alsactl store Device</code> on the Pi, substituting your USB card ID. MIC_GAIN affects only the microphone.</dd><dt>Audio is missing or ambiguous</dt><dd>Check the USB module and extension, then use <code>make pi-check-audio</code> after installation. Choose unique AUDIO_INPUT_DEVICE and AUDIO_OUTPUT_DEVICE names in the installed settings. Device selection does not retune volume or gain.</dd></dl><p><a href="${REPO}/blob/main/docs/software/setup.md" target="_blank" rel="noreferrer">Repository setup documentation ↗</a> · <a href="${REPO}/blob/main/docs/software/maintenance.md" target="_blank" rel="noreferrer">Maintenance and commissioning ↗</a></p></section></article>`;
}

function safetyHTML(){return `<article class="safety-reference"><p class="eyebrow">Before you build</p><h1 tabindex="-1">Safety & responsibility</h1><h2>Your build, your responsibility</h2><p>BlooglyBlob is a DIY electronics and robotics project. You are responsible for selecting components, printing, assembly, wiring, software configuration, inspection, testing, maintenance and use of your build, including any modifications. Evaluate whether you have the skills and equipment to do the work; get qualified help when needed. Following this guide or passing its checks does not establish that a build is safe, compliant or suitable for a particular person or purpose.</p><h2>Children and practical precautions</h2><p>Children must assemble or use the robot only with direct supervision by an adult capable of evaluating the risks and doing the work safely. The adult must control access to tools, electricity, small parts and moving mechanisms. This project is not presented as a certified children’s toy or a substitute for adult care or supervision.</p><ul><li>Soldering, cutting and printing involve hot surfaces, fumes and sharp tools. Follow equipment and material instructions; use suitable ventilation and protective equipment.</li><li>Use the specified enclosed power supply and fuse ratings. Do not open the supply or work on mains wiring. Disconnect power before changing wiring; short circuits can cause burns or fire even at low voltage.</li><li>Keep fingers, hair and clothing away from servos and joints. Keep small parts away from young children and pets.</li><li>Keep the build dry, keep vents clear, and stop using it if wiring is damaged, parts overheat, or movement is obstructed. Do not leave powered tests unattended.</li><li>AI responses can be incorrect or inappropriate. Do not rely on the robot for emergency, medical or other safety-critical decisions.</li></ul><h2>No warranty or safety certification</h2><p>To the fullest extent allowed by applicable law, the project’s designs, print files, software, documentation and build instructions are supplied as is, without express or implied warranties, including merchantability, fitness for a particular purpose and noninfringement. The authors and contributors make no guarantee of accuracy, completeness, reliability, performance or safety, and do not represent that a build meets product-safety standards or regulatory requirements. Diagrams, test results, recommended components and completed checklists are not safety certification.</p><h2>Limits of liability</h2><p>To the fullest extent allowed by applicable law, the authors, contributors and copyright holders disclaim liability for injury, property damage, data loss or other loss arising from building, modifying or using this project. Build and use it at your own risk. Nothing in this notice excludes a liability, warranty or legal right that applicable law does not allow to be excluded. The project license and third-party terms continue to apply; this notice does not replace them or add restrictions to the open-source license.</p><p>See the <a href="${REPO}/blob/main/LICENSE">MIT license</a> and <a href="${REPO}/blob/main/LICENSING.md">license scope</a>.</p></article>`}

function notFound(){return '<p class="eyebrow">Build guide</p><h1 tabindex="-1">Page not found</h1><p>This address doesn’t match a page in the guide.</p><div class="actions"><a class="button primary" href="#start">Meet BlooglyBlob</a><a class="button" href="#parts">Parts & supplies</a></div>'}
const pages={start,parts:arg=>partsHTML(arg),hardware,software,electrical:electricalHTML,safety:safetyHTML,troubleshooting,notes:notesHTML,all:()=>buildSteps.map(s=>stepHTML(s,true)).join('')};
let lastBase=null,partsScroll=0,firstRoute=true;
function route(){
 const hash=decodeURIComponent(location.hash.slice(1)||'start');let [base,arg]=hash.split('/');
 if(base==='content')return;
 if(base==='printing'){base='step-02';history.replaceState(null,'','#'+base+(arg?'/'+encodeURIComponent(arg):''));}
 if(base.startsWith('step-')&&routeAliases[base.slice(5)]){base='step-'+routeAliases[base.slice(5)];history.replaceState(null,'','#'+base);}
 // Plain step numbers such as #14 open that step.
 if(/^\d+$/.test(base)&&buildSteps[+base-1]){location.replace('#step-'+buildSteps[+base-1].id);return}
 if(lastBase==='parts')partsScroll=scrollY;
 const s=base.startsWith('step-')?stepMap[base.slice(5)]:null;
 const known=s||(pages[base]&&(!arg||base==='parts'||(base==='software'&&softwareTopics.includes(arg))));
 $('#page').innerHTML=s?stepHTML(s,false,arg):known?pages[base](arg):notFound();
 document.querySelectorAll('[data-route]').forEach(a=>a.classList.toggle('active',a.dataset.route===base));
 if(base==='parts'){filterParts();$('#search').addEventListener('input',filterParts);$('#category').addEventListener('change',filterParts);$('#stock-filter').addEventListener('change',filterParts)}
 $('#reference-menu').open=base!=='start'&&(!s||s.kind==='service');
 closeMenu();updateProgress();
 document.title=(s?(s.kind==='build'?`Step ${s.number} · ${s.title}`:s.title):known?(refs.find(x=>x[0]===base)?.[1]||'All steps'):'Page not found')+' — BlooglyBlob build guide';
 window.scrollTo(0,base==='parts'&&!arg&&lastBase!=='parts'?partsScroll:0);
 if(base==='step-02'&&partMap[arg]){const plate=prints.find(p=>p.parts.includes(arg));if(plate){$('#plate-settings').open=true;const card=document.getElementById(plate.id);card?.classList.add('selected-plate');card?.scrollIntoView({block:'start'});}}
 lastBase=base;
 document.querySelector('nav a.active')?.scrollIntoView({block:'nearest'});
 if(base==='software'&&softwareTopics.includes(arg)){const section=document.getElementById('software-'+arg);section?.scrollIntoView({block:'start'});section?.querySelector('h2')?.focus({preventScroll:true});}else if(!firstRoute)$('#page h1')?.focus({preventScroll:true});firstRoute=false;
}
function closeMenu(){document.body.classList.remove('menu-open');$('#menu').setAttribute('aria-expanded','false')}
async function copyCode(button){
 const card=button.closest('.code-card'),code=card.querySelector('code'),status=card.querySelector('.copy-status');
 if(button.getAttribute('aria-busy')==='true')return;
 button.setAttribute('aria-busy','true');status.textContent='';
 try{
  if(!navigator.clipboard?.writeText)throw new Error('Clipboard unavailable');
  await navigator.clipboard.writeText(code.textContent);
  status.textContent='Copied.';
 }catch{
  card.querySelector('pre').focus();
  const range=document.createRange();range.selectNodeContents(code);
  const selection=window.getSelection();selection.removeAllRanges();selection.addRange(range);
  status.textContent='Copy is unavailable. Text selected: press Ctrl+C or Command+C, or use your device’s Copy menu.';
 }finally{button.removeAttribute('aria-busy');}
}
document.addEventListener('click',e=>{
 const copy=e.target.closest('[data-copy-code]');
 if(copy){copyCode(copy);return;}
 const summary=e.target.closest('.reference-topic > summary');
 if(summary&&summary.parentElement.open){e.preventDefault();summary.parentElement.open=false;document.querySelector(`[aria-controls="${summary.parentElement.id}"]`)?.focus()}
 const topic=e.target.closest('[data-reference]');
 if(topic){const selected=document.getElementById(topic.getAttribute('aria-controls'));document.querySelectorAll('.reference-topic').forEach(el=>el.open=el===selected);selected.querySelector('summary').focus();selected.scrollIntoView({block:'start',behavior:'instant'})}
 const wiringDetail=e.target.closest('[data-wiring-detail]');
 if(wiringDetail){const view=document.querySelector('.master-window'),large=view.classList.toggle('is-detail');wiringDetail.setAttribute('aria-pressed',String(large));wiringDetail.textContent=large?'Fit diagram':'Larger labels';view.scrollTo({top:0,left:0,behavior:'instant'});view.focus({preventScroll:true})}
 const z=e.target.closest('[data-zoom]');
 if(z){$('#zoom').classList.remove('large');$('#zoom-image').classList.remove('detail-size');$('#detail-size').textContent='Larger view';$('#detail-size').setAttribute('aria-pressed','false');$('#zoom-image').src=z.dataset.zoom;$('#zoom-image').alt=z.querySelector('img')?.alt||z.closest('figure')?.querySelector('img')?.alt||'Enlarged diagram';$('#zoom').showModal()}
 if(e.target.id==='all-steps')location.hash='all';
 if(e.target.closest('.skip')){e.preventDefault();$('#content').focus()}
 if(document.body.classList.contains('menu-open')&&!e.target.closest('aside')&&!e.target.closest('#menu'))closeMenu();
});
document.addEventListener('toggle',e=>{if(!e.target.matches('.reference-topic'))return;const control=document.querySelector(`[aria-controls="${e.target.id}"]`);control?.setAttribute('aria-expanded',String(e.target.open));if(!e.target.open&&e.target.contains(document.activeElement))control?.focus()},true);
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.body.classList.contains('menu-open')){closeMenu();$('#menu').focus()}});
document.addEventListener('change',e=>{const s=e.target.dataset.step,p=e.target.dataset.stock;if(s){state.steps=e.target.checked?[...new Set([...state.steps,s])]:state.steps.filter(x=>x!==s);save()}if(p){state.stock=e.target.checked?[...new Set([...state.stock,p])]:state.stock.filter(x=>x!==p);save()}});
$('#detail-size').onclick=()=>{const large=$('#zoom-image').classList.toggle('detail-size');$('#zoom').classList.toggle('large',large);$('#detail-size').textContent=large?'Fit to screen':'Larger view';$('#detail-size').setAttribute('aria-pressed',String(large))};
$('#close-zoom').onclick=()=>$('#zoom').close();$('#zoom').addEventListener('click',e=>{if(e.target===$('#zoom'))$('#zoom').close()});
$('#menu').onclick=()=>{const open=document.body.classList.toggle('menu-open');$('#menu').setAttribute('aria-expanded',String(open));if(open)document.querySelector('nav a.active')?.scrollIntoView({block:'nearest'})};
// Print includes collapsed inventories and electrical lookup sections; restore the screen state afterward.
let printInventories=[];
window.addEventListener('beforeprint',()=>{printInventories=[...document.querySelectorAll('.bench-list:not([open]), .electrical-reference details:not([open])')];printInventories.forEach(el=>el.open=true)});
window.addEventListener('afterprint',()=>{printInventories.forEach(el=>el.open=false);printInventories=[]});
window.addEventListener('hashchange',route);route();
